solution.solution.cpp:
#include <atomic>
#include <cstdint>

constexpr uint32_t IID_IStone  = 1;
constexpr uint32_t IID_IStone2 = 2;
constexpr int32_t OK = 0, NOT_SUPPORTED = 1, INVALID_ARGUMENT = 2;

struct IStone
{
    virtual int32_t  QueryInterface(uint32_t iid, void** out) = 0;
    virtual uint32_t AddRef() = 0;
    virtual uint32_t Release() = 0;
    virtual int32_t  Weight() = 0;
};

struct IStone2 : IStone
{
    virtual int32_t Hardness() = 0;
};

namespace
{
    std::atomic<int> g_live{ 0 };

    class Stone final : public IStone2
    {
    public:
        Stone(int32_t weight, int32_t hardness) : m_weight{ weight }, m_hardness{ hardness } { ++g_live; }

        int32_t QueryInterface(uint32_t iid, void** out) override
        {
            if (!out) return INVALID_ARGUMENT;
            if (iid == IID_IStone || (iid == IID_IStone2 && m_hardness > 0))
            {
                *out = iid == IID_IStone2 ? static_cast<void*>(static_cast<IStone2*>(this)) : static_cast<void*>(static_cast<IStone*>(this));
                AddRef();
                return OK;
            }
            *out = nullptr;
            return NOT_SUPPORTED;
        }
        uint32_t AddRef() override { return ++m_refs; }
        uint32_t Release() override
        {
            const uint32_t left{ --m_refs };
            if (left == 0) delete this;
            return left;
        }
        int32_t Weight() override { return m_weight; }
        int32_t Hardness() override { return m_hardness; }

    private:
        ~Stone() { --g_live; }
        std::atomic<uint32_t> m_refs{ 1 };
        int32_t m_weight;
        int32_t m_hardness;
    };
}

int32_t CreateStone(int32_t weight, int32_t hardness, IStone** out)
{
    if (!out) return INVALID_ARGUMENT;
    *out = new Stone(weight, hardness);
    return OK;
}

int liveStones()
{
    return g_live;
}

unitTests:
TEST("create and release") { const int before = liveStones(); IStone* s = nullptr; CHECK_EQ(CreateStone(7, 3, &s), OK); CHECK_EQ(s->Weight(), 7); CHECK_EQ(liveStones(), before + 1); CHECK_EQ(s->Release(), 0u); CHECK_EQ(liveStones(), before); }
TEST("AddRef keeps it alive") { const int before = liveStones(); IStone* s = nullptr; CreateStone(1, 1, &s); CHECK_EQ(s->AddRef(), 2u); CHECK_EQ(s->Release(), 1u); CHECK_EQ(liveStones(), before + 1); s->Release(); CHECK_EQ(liveStones(), before); }
TEST("ask for IStone2") {
    const int before = liveStones(); IStone* s = nullptr; CreateStone(9, 6, &s);
    void* p = nullptr; CHECK_EQ(s->QueryInterface(IID_IStone2, &p), OK); CHECK(p != nullptr);
    IStone2* s2 = static_cast<IStone2*>(p); CHECK_EQ(s2->Hardness(), 6); CHECK_EQ(s2->Weight(), 9);
    CHECK_EQ(s->Release(), 1u); CHECK_EQ(liveStones(), before + 1); CHECK_EQ(s2->Release(), 0u); CHECK_EQ(liveStones(), before);
}
TEST("a plain stone has no IStone2") {
    const int before = liveStones(); IStone* s = nullptr; CreateStone(4, 0, &s);
    void* p = reinterpret_cast<void*>(1); CHECK_EQ(s->QueryInterface(IID_IStone2, &p), NOT_SUPPORTED); CHECK(p == nullptr);
    CHECK_EQ(s->QueryInterface(IID_IStone, &p), OK); static_cast<IStone*>(p)->Release();
    CHECK_EQ(s->Release(), 0u); CHECK_EQ(liveStones(), before);
}
TEST("unknown interface and bad arguments") { IStone* s = nullptr; CreateStone(1, 1, &s); void* p = nullptr; CHECK_EQ(s->QueryInterface(99, &p), NOT_SUPPORTED); CHECK_EQ(s->QueryInterface(IID_IStone, nullptr), INVALID_ARGUMENT); s->Release(); CHECK_EQ(CreateStone(1, 1, nullptr), INVALID_ARGUMENT); }

